for name, cols in sets.items():
 r=model(cols,1,robust=.3); E.append(r[3]);
 xx=X[:,[IDX[c] for c in cols]];reg=np.eye(len(cols))*1;reg[0,0]=0; beta=np.linalg.solve(xx.T@xx+reg,xx.T@Y)
 for i in range(15):
  res=Y-xx@beta; wt=1/np.maximum(1,np.abs(res)/.3); beta=np.linalg.solve((xx.T*wt)@xx+reg,(xx.T*wt)@Y)
 print(name,'LOPO',round(r[0],3),'coefs', [(c,round(b,3)) for c,b in zip(cols,beta)])
