for wt in [(1,0,0),(.5,.5,0),(.5,0,.5),(0,0,1),(.3,.2,.5)]:
 e=sum(w*x for w,x in zip(wt,E)); print(wt,'MAE',np.mean([np.mean(abs(e[P==p])) for p in people]), 'qabs',np.quantile(abs(e),[.8,.85,.9,.95]),'q signed',np.quantile(e,[.05,.95])); print([(p,round(float(np.mean(e[P==p])),3),round(float(np.mean(abs(e[P==p]))),3)) for p in people])
